import Config

# Note we also include the path to a cache manifest
# containing the digested version of static files. This
# manifest is generated by the `mix assets.deploy` task,
# which you should run after static files are built and
# before starting your production server.
config :fleetms, FleetmsWeb.Endpoint, cache_static_manifest: "priv/static/cache_manifest.json"

# Force using SSL in production. This also sets the "strict-security-transport" header,
# known as HSTS. If you have a health check endpoint, you may want to exclude it below.
# Note `:force_ssl` is required to be set at compile-time.
config :fleetms, FleetmsWeb.Endpoint,
  force_ssl: [
    rewrite_on: [:x_forwarded_proto],
    exclude: [
      paths: ["/health"],
      hosts: ["localhost", "127.0.0.1"]
    ]
  ]

# Configure Swoosh API Client
config :swoosh, api_client: Swoosh.ApiClient.Req

# Disable Swoosh Local Memory Storage
config :swoosh, local: false

# No transactional-email provider is wired for the demo. Route mail to the Logger
# adapter so flows that send email (registration confirmation, invites, digests)
# just log instead of sending. Without this, the default Local adapter would try
# to reach its in-memory store — disabled above — and crash the calling action
# (e.g. user registration). Swap this for a real adapter (see runtime.exs) to
# actually deliver mail.
config :fleetms, Fleetms.Mailer, adapter: Swoosh.Adapters.Logger

# User uploads (vehicle photos, inspection images, documents) persist on a Fly
# volume mounted at /data (see fly.toml [[mounts]]), so they survive redeploys.
# Both the local-storage writer and the /uploads static route point at it. (When
# S3_BUCKET is set in runtime.exs the S3 adapter takes over and these are unused.)
config :fleetms, :uploads_dir, "/data/uploads"
config :fleetms, Fleetms.Storage.Local, base_dir: "/data/uploads"

# Apply per-tenant schema migrations in the background on boot, so the deploy's
# release_command only has to migrate the public schema. See Fleetms.TenantMigrations.
config :fleetms, :migrate_tenants_on_boot, true

# Do not print debug messages in production
config :logger, level: :info

# Runtime production configuration, including reading
# of environment variables, is done on config/runtime.exs.
